using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using RPGModder.Core.Merge;
using RPGModder.Core.Models;
using RPGModder.Core.Operations;
using System.Security.Cryptography;
using System.Text;
using Xunit;

namespace RPGModder.Tests.MergeContract;

public sealed class PluginMergeContractTests
{
    private const string VanillaPluginsJs =
        "// Generated by RPG Maker.\n" +
        "// Do not edit this file directly.\n" +
        "var $plugins =\n" +
        "[\n" +
        "{\"name\":\"Alpha\",\"status\":true,\"description\":\"First base plugin.\",\"parameters\":{\"fontSize\":\"16\",\"Font Size\":\"18\"}},\n" +
        "{\"name\":\"Omega\",\"status\":true,\"description\":\"Second base plugin.\",\"parameters\":{}}\n" +
        "];\n";

    [Fact]
    public void Build_PluginsJsWithUnparseableArray_IsParseFailedOnTheMod()
    {
        BaseFileSet baseFiles = BaseFileSet.From(new[]
        {
            CreateBaseFile("js/plugins.js", VanillaPluginsJs)
        });

        const string brokenPluginsJs =
            "// Generated by RPG Maker.\n" +
            "var $plugins =\n" +
            "[\n" +
            "{\"name\":\"Alpha\", broken\n" +
            "];\n";

        ModSource mod = new(
            "a-broken-plugins",
            0,
            new[] { CreateModFile("js/plugins.js", "js/plugins.js", brokenPluginsJs) },
            Array.Empty<ModPatch>(),
            Array.Empty<PluginEntry>());

        ModChangeSet changeSet = ChangeSetBuilder.Build(mod, baseFiles);

        OperationDiagnostic diag = Assert.Single(changeSet.Diagnostics);
        Assert.Equal(DiagnosticCodes.MergeParseFailed, diag.Code);
        Assert.Equal(DiagnosticSeverity.Error, diag.Severity);
        Assert.Equal("a-broken-plugins", diag.Subject);
        Assert.Empty(changeSet.Ops);
    }

    [Fact]
    public void Build_PluginRegisteredThroughPluginsRegistry_GivesAddRecordAndAfterAnchor()
    {
        BaseFileSet baseFiles = BaseFileSet.From(new[]
        {
            CreateBaseFile("js/plugins.js", VanillaPluginsJs)
        });

        PluginEntry entry = JsonConvert.DeserializeObject<PluginEntry>(
            "{\"name\":\"AshExtra\",\"status\":true,\"description\":\"Added by ash.\",\"parameters\":{\"mode\":\"fast\"}}")!;

        ModSource mod = new(
            "a-ash",
            0,
            Array.Empty<ModFile>(),
            Array.Empty<ModPatch>(),
            new[] { entry });

        ModChangeSet changeSet = ChangeSetBuilder.Build(mod, baseFiles);

        Assert.Empty(changeSet.Diagnostics);
        RecordKey pluginKey = new("js/plugins.js", "plugin:AshExtra");

        ChangeOp addOp = Assert.Single(changeSet.Ops, op => op.Key == pluginKey && op.Kind == ChangeKind.AddRecord);
        Assert.Equal("", addOp.Path);
        JObject expectedEntry = JObject.Parse(
            "{\"name\":\"AshExtra\",\"status\":true,\"description\":\"Added by ash.\",\"parameters\":{\"mode\":\"fast\"}}");
        Assert.True(JToken.DeepEquals(expectedEntry, addOp.Value));
        Assert.Equal(
            new[] { "name", "status", "description", "parameters" },
            ((JObject)addOp.Value!).Properties().Select(p => p.Name));

        ChangeOp afterOp = Assert.Single(changeSet.Ops, op => op.Key == pluginKey && op.Path == "@after");
        Assert.Equal(ChangeKind.SetLeaf, afterOp.Kind);
        Assert.Equal("Omega", afterOp.Value!.Value<string>());
    }

    [Fact]
    public void Build_PluginLeafEdits_UseIdentifierAndBracketParameterPaths()
    {
        BaseFileSet baseFiles = BaseFileSet.From(new[]
        {
            CreateBaseFile("js/plugins.js", VanillaPluginsJs)
        });

        const string modPluginsJs =
            "// Generated by RPG Maker.\n" +
            "// Do not edit this file directly.\n" +
            "var $plugins =\n" +
            "[\n" +
            "{\"name\":\"Alpha\",\"status\":false,\"description\":\"First base plugin.\",\"parameters\":{\"fontSize\":\"20\",\"Font Size\":\"24\"}},\n" +
            "{\"name\":\"Omega\",\"status\":true,\"description\":\"Second base plugin.\",\"parameters\":{}}\n" +
            "];\n";

        ModSource mod = new(
            "a-params",
            0,
            new[] { CreateModFile("js/plugins.js", "js/plugins.js", modPluginsJs) },
            Array.Empty<ModPatch>(),
            Array.Empty<PluginEntry>());

        ModChangeSet changeSet = ChangeSetBuilder.Build(mod, baseFiles);

        Assert.Empty(changeSet.Diagnostics);
        RecordKey alphaKey = new("js/plugins.js", "plugin:Alpha");

        Assert.Single(changeSet.Ops, op => op.Key == alphaKey && op.Path == "status" && op.Value!.Value<bool>() == false);
        Assert.Single(changeSet.Ops, op => op.Key == alphaKey && op.Path == "parameters.fontSize" && op.Value!.Value<string>() == "20");
        Assert.Single(changeSet.Ops, op => op.Key == alphaKey && op.Path == "parameters['Font Size']" && op.Value!.Value<string>() == "24");
    }

    [Fact]
    public void Compose_TwoModsGivingOneEntryDifferentAnchors_GivesNonBlockingPluginOrderClashWithDefaultApplied()
    {
        BaseFileSet baseFiles = BaseFileSet.From(new[]
        {
            CreateBaseFile("js/plugins.js", VanillaPluginsJs)
        });

        const string modAPluginsJs =
            "// Generated by RPG Maker.\n" +
            "// Do not edit this file directly.\n" +
            "var $plugins =\n" +
            "[\n" +
            "{\"name\":\"Alpha\",\"status\":true,\"description\":\"First base plugin.\",\"parameters\":{\"fontSize\":\"16\",\"Font Size\":\"18\"}},\n" +
            "{\"name\":\"SharedPlugin\",\"status\":true,\"description\":\"Shared.\",\"parameters\":{}},\n" +
            "{\"name\":\"Omega\",\"status\":true,\"description\":\"Second base plugin.\",\"parameters\":{}}\n" +
            "];\n";

        const string modBPluginsJs =
            "// Generated by RPG Maker.\n" +
            "// Do not edit this file directly.\n" +
            "var $plugins =\n" +
            "[\n" +
            "{\"name\":\"Alpha\",\"status\":true,\"description\":\"First base plugin.\",\"parameters\":{\"fontSize\":\"16\",\"Font Size\":\"18\"}},\n" +
            "{\"name\":\"Omega\",\"status\":true,\"description\":\"Second base plugin.\",\"parameters\":{}},\n" +
            "{\"name\":\"SharedPlugin\",\"status\":true,\"description\":\"Shared.\",\"parameters\":{}}\n" +
            "];\n";

        ModChangeSet csA = ChangeSetBuilder.Build(
            new ModSource(
                "a-ash",
                0,
                new[] { CreateModFile("js/plugins.js", "js/plugins.js", modAPluginsJs) },
                Array.Empty<ModPatch>(),
                Array.Empty<PluginEntry>()),
            baseFiles);

        ModChangeSet csB = ChangeSetBuilder.Build(
            new ModSource(
                "b-birch",
                1,
                new[] { CreateModFile("js/plugins.js", "js/plugins.js", modBPluginsJs) },
                Array.Empty<ModPatch>(),
                Array.Empty<PluginEntry>()),
            baseFiles);

        MergePlan plan = Composer.Compose(new[] { csA, csB }, Array.Empty<Resolution>(), baseFiles);

        Assert.True(plan.IsDeployable);
        Collision clash = Assert.Single(plan.Collisions);
        Assert.Equal(CollisionKind.PluginOrderClash, clash.Kind);
        Assert.Equal(new RecordKey("js/plugins.js", "plugin:SharedPlugin"), clash.Key);
        Assert.Equal("@after", clash.Path);
        Assert.False(clash.Blocking);
        Assert.Equal(new[] { ResolutionKind.PickMod, ResolutionKind.KeepBothInProfileOrder }, clash.Allowed);

        CollisionOutcome outcome = Assert.Single(plan.Outcomes);
        Assert.Equal(clash.Id, outcome.CollisionId);
        Assert.Equal(ResolutionSource.Default, outcome.Source);

        IReadOnlyList<MergedFile> written = MergedFileWriter.Write(plan, baseFiles, systemVersionId: null);
        MergedFile pluginsFile = Assert.Single(written);
        Assert.Equal("js/plugins.js", pluginsFile.File);
        Assert.Equal(modBPluginsJs, pluginsFile.Text);
    }

    [Fact]
    public void Compose_OrderAmbiguousWithPickMod_PutsPickedModsEntriesFirst()
    {
        BaseFileSet baseFiles = BaseFileSet.From(new[]
        {
            CreateBaseFile("js/plugins.js", VanillaPluginsJs)
        });

        PluginEntry entryA = JsonConvert.DeserializeObject<PluginEntry>(
            "{\"name\":\"AshExtra\",\"status\":true,\"description\":\"Added by ash.\",\"parameters\":{}}")!;
        PluginEntry entryB = JsonConvert.DeserializeObject<PluginEntry>(
            "{\"name\":\"BirchExtra\",\"status\":true,\"description\":\"Added by birch.\",\"parameters\":{}}")!;

        ModChangeSet csA = ChangeSetBuilder.Build(
            new ModSource("a-ash", 0, Array.Empty<ModFile>(), Array.Empty<ModPatch>(), new[] { entryA }),
            baseFiles);
        ModChangeSet csB = ChangeSetBuilder.Build(
            new ModSource("b-birch", 1, Array.Empty<ModFile>(), Array.Empty<ModPatch>(), new[] { entryB }),
            baseFiles);

        MergePlan defaultPlan = Composer.Compose(new[] { csA, csB }, Array.Empty<Resolution>(), baseFiles);
        Collision collision = Assert.Single(defaultPlan.Collisions);
        Assert.Equal(CollisionKind.OrderAmbiguous, collision.Kind);
        Assert.Equal(new RecordKey("js/plugins.js", "plugin:Omega"), collision.Key);
        Assert.Equal("@after", collision.Path);
        Assert.False(collision.Blocking);

        CollisionOutcome defaultOutcome = Assert.Single(defaultPlan.Outcomes);
        Assert.Equal(ResolutionSource.Default, defaultOutcome.Source);
        Assert.Equal(ResolutionKind.KeepBothInProfileOrder, defaultOutcome.Kind);

        MergePlan pickedPlan = Composer.Compose(
            new[] { csA, csB },
            new[] { new Resolution(collision.Id, ResolutionKind.PickMod, "b-birch", collision.Fingerprint) },
            baseFiles);

        Assert.True(pickedPlan.IsDeployable);
        IReadOnlyList<MergedFile> written = MergedFileWriter.Write(pickedPlan, baseFiles, systemVersionId: null);
        MergedFile file = Assert.Single(written);

        const string expectedPickedText =
            "// Generated by RPG Maker.\n" +
            "// Do not edit this file directly.\n" +
            "var $plugins =\n" +
            "[\n" +
            "{\"name\":\"Alpha\",\"status\":true,\"description\":\"First base plugin.\",\"parameters\":{\"fontSize\":\"16\",\"Font Size\":\"18\"}},\n" +
            "{\"name\":\"Omega\",\"status\":true,\"description\":\"Second base plugin.\",\"parameters\":{}},\n" +
            "{\"name\":\"BirchExtra\",\"status\":true,\"description\":\"Added by birch.\",\"parameters\":{}},\n" +
            "{\"name\":\"AshExtra\",\"status\":true,\"description\":\"Added by ash.\",\"parameters\":{}}\n" +
            "];\n";

        Assert.Equal(expectedPickedText, file.Text);
    }

    private static BaseFile CreateBaseFile(string path, string text)
    {
        string sha = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
        return new BaseFile(path, text, sha);
    }

    private static ModFile CreateModFile(string target, string source, string text)
    {
        string sha = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
        return new ModFile(target, source, text, sha);
    }
}
